using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Threading.Tasks;
sealed partial class WorkspaceWindow {
 void KeepClosedTabRecovery(WorkTab tab){string snapshot=Path.Combine(tab.folder,"snapshot.json"),restore=Path.Combine(tab.folder,"restore.json");string source=File.Exists(snapshot)?snapshot:File.Exists(restore)?restore:null;if(source==null)return;string recovery=Path.Combine(root,"Sessions",Guid.NewGuid().ToString()),id=Guid.NewGuid().ToString(),folder=Path.Combine(recovery,id);Directory.CreateDirectory(folder);Atomic(Path.Combine(folder,Path.GetFileName(source)),ReadShared(source));Atomic(Path.Combine(recovery,"session.json"),json.Serialize(new[]{new{id=id,studio=tab.studio,name=tab.title,detached=false}}));}
 bool closingAllTabs;
 async Task CloseAllTabs(bool confirm=true){if(closingAllTabs||items.Count==0){if(items.Count==0)SetStatus("There are no open tabs to close.");return;}if(confirm){using(var choice=new Form{Text="Close all tabs",StartPosition=FormStartPosition.CenterParent,ClientSize=new Size(560,180),FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,BackColor=BackColor,ForeColor=ForeColor}){var message=new Label{Text="Save this workspace before closing all tabs?\nLocal recovery is kept. Detached studio windows stay open.",AutoSize=false,Dock=DockStyle.Top,Height=95,Padding=new Padding(20)};var buttons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=65,Padding=new Padding(12),FlowDirection=FlowDirection.RightToLeft};foreach(var p in new[]{Tuple.Create("Cancel",DialogResult.Cancel),Tuple.Create("Close tabs",DialogResult.No),Tuple.Create("Save workspace & close",DialogResult.Yes)}){var b=new Button{Text=p.Item1,DialogResult=p.Item2,AutoSize=true,Padding=new Padding(8),FlatStyle=FlatStyle.Flat,BackColor=BackColor,ForeColor=ForeColor};buttons.Controls.Add(b);if(p.Item2==DialogResult.Cancel)choice.CancelButton=b;}choice.Controls.Add(message);choice.Controls.Add(buttons);var result=choice.ShowDialog(this);if(result==DialogResult.Cancel)return;if(result==DialogResult.Yes&&!await Save())return;}}closingAllTabs=true;try{CloseCompanionDock();int count=0;foreach(var tab in items.ToArray()){SetStatus("Closing "+studios[tab.studio]+"…");if(!await CloseDocumentTab(tab)){string reason=status.Text;SetStatus("Closed "+count+" tabs. Remaining tabs stayed open. "+reason);return;}count++;}tabs.SelectedTab=home;SetStatus("All tabs closed. Detached windows remain open.");}finally{closingAllTabs=false;}}
}
